// ============================================================
// ICP CLASSIFICATION CODE NODE (Hardcoded Lists)
// Matches Python notebook logic exactly
// ============================================================

const red_flag_industries = new Set([
  "Home Improvement", "Home Renovation", "Adult", "Adventure Travel", "American Football"
]);

const score_negative_industries = new Set([
  "Food and Beverage", "Real Estate", "Mobile", "Subscription Service", "Video on Demand"
]);

const score_non_tech_industries = new Set([
  "Consulting", "Customer Service", "Security", "Archiving Service", "Commercial"
]);

const score_tech_industries = new Set([
  "Ediscovery", "Information Services", "Professional Services", "SEO", "Technical Support"
]);

function determine_status(industries_str) {
  if (typeof industries_str !== "string" || industries_str.trim() === "") return "Irrelevant";
  const industries = industries_str.split(",").map(i => i.trim());
  for (const ind of industries) {
    if (red_flag_industries.has(ind)) return "Irrelevant";
  }
  let score = 0, tech_count = 0, non_tech_count = 0;
  for (const ind of industries) {
    if (score_negative_industries.has(ind)) score -= 1;
    if (score_non_tech_industries.has(ind)) { score += 1; non_tech_count += 1; }
    if (score_tech_industries.has(ind))     { score += 1; tech_count += 1; }
  }
  if (score < 0) return "Irrelevant";
  if (score === 0 && tech_count === 0 && non_tech_count === 0) return "Irrelevant";
  if (tech_count > non_tech_count) return "Tech";
  if (non_tech_count > tech_count) return "Non-Tech";
  return "Tech";
}

const companies = $input.all();
return companies.map(item => {
  const industriesStr = item.json.cb_industries;
  const companyIdRaw  = item.json.company_id;
  return {
    json: {
      company_id: companyIdRaw != null ? parseInt(companyIdRaw, 10) : null,
      cb_industries: industriesStr,
      industry_status: determine_status(industriesStr)
    },
  };
});

const items = $input.all();
const results = [];
for (const item of items) {
  const companyId = $('Loop Over Items').item?.json?.company_id ?? item.json?.company_id;
  let aiResult = { is_b2b: false, confidence: 'low', reasoning: 'Parse failed', suggested_industry: '' };
  try {
    const content = item.json.output?.[0]?.content?.[0]?.text || item.json.choices?.[0]?.message?.content || '{}';
    aiResult = JSON.parse(content);
  } catch (e) {
    aiResult.reasoning = 'Failed to parse OpenAI response: ' + e.message;
  }
  let newScore = 'Irrelevant';
  if (aiResult.is_b2b === true) {
    if (aiResult.confidence === 'high' || aiResult.confidence === 'medium') {
      const suggested = (aiResult.suggested_industry || '').toLowerCase();
      if (suggested.includes('tech') || suggested.includes('software') || suggested.includes('saas') || suggested.includes('it')) {
        newScore = 'Tech';
      } else {
        newScore = 'Non-Tech';
      }
    }
  }
  results.push({
    json: {
      company_id: companyId,
      original_score: 'Irrelevant',
      new_score: newScore,
      is_b2b: aiResult.is_b2b,
      confidence: aiResult.confidence,
      reasoning: aiResult.reasoning,
      suggested_industry: aiResult.suggested_industry || '',
      was_rescored: newScore !== 'Irrelevant'
    }
  });
}
return results;

const items = $input.all();
return items.map(item => {
  let html = item.json.data || '';
  let clean = html
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .substring(0, 3000);
  return {
    json: {
      ...item.json,
      clean_content: clean
    }
  };
});
